import { readFile, writeFile, access } from 'node:fs/promises';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
import { base, root, stateDir, project, component, json, runDocker, allResults, locales, request, languageCode } from './weblate-client.mjs';
// A personal token is generated by Weblate at account creation. Capture it privately.
try { await access(join(stateDir,'api-token')); } catch {
  const stdout = await runDocker(['exec','-T','--user','weblate','weblate','weblate','shell','-c',"from weblate.auth.models import User; print('API_TOKEN=' + User.objects.get(username='admin').auth_token.key)"]);
  const match = stdout.match(/API_TOKEN=([^\s]+)/);
  if(!match)throw new Error('Could not initialize API credentials; wait until Weblate finishes its first startup.');
  await writeFile(join(stateDir,'api-token'),match[1]+'\n',{mode:0o600,flag:'wx'});
}
const instructions='Translate naturally and accurately for a software engineer’s portfolio. Keep technology names, code identifiers, model names and units in English. Preserve benchmark scope, quality limitations, dates and the public demo’s disabled generation status. Machine-generated suggestions must remain editable and be reviewed before publication.';
let projects=await allResults('/api/projects/');
if(!projects.some(p=>p.slug===project))await json('/api/projects/','POST',{name:'Taha Chelly Website',slug:project,web:'https://tahachelly.com/',access_control:100,public_sharing:false,use_shared_tm:false,contribute_shared_tm:false});
await json(`/api/projects/${project}/`,'PATCH',{instructions,translation_review:true,source_review:true,use_shared_tm:false,contribute_shared_tm:false});
let components=await allResults(`/api/projects/${project}/components/`);
if(!components.some(c=>c.slug===component)) {
  const zip=join(stateDir,'initial-locales.zip');
  const packed=spawnSync('python3',['-c',"import pathlib,sys,zipfile; root=pathlib.Path(sys.argv[1]); z=zipfile.ZipFile(sys.argv[2],'w',zipfile.ZIP_DEFLATED); [z.write(root/'src/data/i18n'/f'{l}.json',f'locales/{l}.json') for l in ['en','ar','es','de','fr','it','zh','ja']]; z.close()",root,zip],{encoding:'utf8'});
  if(packed.status!==0)throw new Error('Could not package locale files: '+packed.stderr);
  const form=new FormData();
  const settings={name:'Website & engineering notebook',slug:component,repo:'local:',vcs:'local',branch:'main',filemask:'locales/*.json',template:'locales/en.json',file_format:'json',language_regex:'^(en|ar|es|de|fr|it|zh|ja)$',source_language:'en',new_lang:'none',manage_units:true,enable_suggestions:true,suggestion_autoaccept:0,check_flags:'check-glossary',push_on_commit:false,push_on_update:false};
  for(const [key,value] of Object.entries(settings))form.set(key,String(value));
  form.set('zipfile',new Blob([await readFile(zip)],{type:'application/zip'}),'initial-locales.zip');
  await request(`/api/projects/${project}/components/`,{method:'POST',body:form});
}
// Creation/import happens in a background task; wait for the translation scan.
let ready=false;
for(let attempt=0;attempt<100;attempt++) {
  try {const translations=await allResults(`/api/components/${project}/${component}/translations/`);if(translations.length===locales.length){const mapping=Object.fromEntries(translations.map(t=>[t.filename.split('/').pop().replace(/\.json$/, ''),t.language.code]));await writeFile(join(stateDir,'language-map.json'),JSON.stringify(mapping,null,2)+'\n',{mode:0o600});console.log(`Connected ${translations.length} locales, ${translations[0].total} strings each.`);ready=true;break;}}catch{}
  if(attempt%10===0)console.log('Waiting for Weblate to scan the imported locale files...');
  await new Promise(resolve=>setTimeout(resolve,3000));
}
if(!ready)throw new Error('Weblate has not finished scanning; run this command again after checking the component in Weblate.');
components=await allResults(`/api/projects/${project}/components/`);
let glossary=components.find(c=>c.is_glossary);
if(!glossary)throw new Error('The project glossary was not created. Check Weblate project settings.');
// Each protected term appears unchanged in every glossary language.
const terms=JSON.parse(await readFile(join(root,'src/data/i18n/glossary.json'),'utf8')).terms;
const translations=await allResults(`/api/components/${project}/${glossary.slug}/translations/`);
for(const translation of translations) {
  const lang=translation.language.code;
  const path=`/api/translations/${project}/${glossary.slug}/${lang}/units/`;
  const existing=await allResults(path+'?page_size=1000');
  for(const term of terms) {
    const unit=existing.find(u=>u.source?.[0]===term);
    if(!unit){await json(path,'POST',{source:[term],target:[term],state:20});}
  }
}
const sourceUnits=await allResults(`/api/translations/${project}/${glossary.slug}/en/units/?page_size=1000`);
for(const unit of sourceUnits) {
  if(terms.includes(unit.source[0]))await json(`/api/units/${unit.id}/`,'PATCH',{extra_flags:'read-only, terminology',explanation:'Technical term: keep unchanged in every language.'});
}
// Explain context directly in the editor for each English source message.
const units=await allResults(`/api/translations/${project}/${component}/en/units/?page_size=1000`);
for(const unit of units)if(!unit.explanation)await json(`/api/units/${unit.id}/`,'PATCH',{explanation:instructions});
const baselinePath=join(stateDir,'baseline.json');
try { await access(baselinePath); } catch {
  const baseline={};
  for(const locale of locales)baseline[locale]=await (await request(`/api/translations/${project}/${component}/${await languageCode(locale)}/file/`)).json();
  await writeFile(baselinePath,JSON.stringify(baseline,null,2)+'\n',{mode:0o600,flag:'wx'});
}
console.log(`Weblate connected: ${base}/projects/${project}/${component}/\nSuggestions stay editable; importing and publishing are explicit steps.`);
